/**
 * ReputeX v3 Bundled Network Graph Canvas Renderer Engine (Firefox Build)
 * MV3 CSP Compliant Force-Directed Canvas Network Graph.
 */
(function(global) {
  function NetworkGraph(container, options) {
    this.container = typeof container === 'string' ? document.getElementById(container) : container;
    this.canvas = document.createElement('canvas');
    this.ctx = this.canvas.getContext('2d');
    this.container.appendChild(this.canvas);

    this.nodes = [];
    this.edges = [];
    this.options = options || {};

    this.width = this.container.clientWidth || 340;
    this.height = this.container.clientHeight || 220;

    this.canvas.width = this.width;
    this.canvas.height = this.height;

    this.scale = 1;
    this.offsetX = 0;
    this.offsetY = 0;

    this.animId = null;
    this.selectedNode = null;
  }

  NetworkGraph.prototype.setData = function(data) {
    const self = this;
    this.nodes = (data.nodes || []).map((n, i) => {
      const angle = (i / data.nodes.length) * 2 * Math.PI;
      const radius = n.isRoot ? 0 : (n.isHop2 ? 80 : 45);
      return {
        id: n.id,
        label: n.label || n.id,
        riskScore: n.riskScore || 80,
        isRoot: !!n.isRoot,
        x: self.width / 2 + Math.cos(angle) * radius + (Math.random() * 10 - 5),
        y: self.height / 2 + Math.sin(angle) * radius + (Math.random() * 10 - 5),
        vx: 0,
        vy: 0,
        radius: n.isRoot ? 14 : 9
      };
    });

    this.nodeMap = new Map();
    this.nodes.forEach(n => this.nodeMap.set(n.id, n));

    this.edges = (data.edges || []).map(e => ({
      fromNode: self.nodeMap.get(e.from),
      toNode: self.nodeMap.get(e.to),
      label: e.label || ''
    })).filter(e => e.fromNode && e.toNode);

    this.startPhysics();
  };

  NetworkGraph.prototype.startPhysics = function() {
    const self = this;
    let step = 0;

    if (this.animId) cancelAnimationFrame(this.animId);

    function loop() {
      if (step < 120) {
        self._simulatePhysics();
        step++;
      }
      self.render();
      self.animId = requestAnimationFrame(loop);
    }
    loop();
  };

  NetworkGraph.prototype._simulatePhysics = function() {
    const self = this;
    const k = 0.05;
    const damping = 0.85;

    for (let i = 0; i < this.nodes.length; i++) {
      for (let j = i + 1; j < this.nodes.length; j++) {
        const n1 = this.nodes[i];
        const n2 = this.nodes[j];
        const dx = n2.x - n1.x;
        const dy = n2.y - n1.y;
        const dist = Math.sqrt(dx * dx + dy * dy) || 1;
        const force = (k * 1000) / (dist * dist);

        const fx = (dx / dist) * force;
        const fy = (dy / dist) * force;

        if (!n1.isRoot) { n1.vx -= fx; n1.vy -= fy; }
        if (!n2.isRoot) { n2.vx += fx; n2.vy += fy; }
      }
    }

    for (let i = 0; i < this.edges.length; i++) {
      const e = this.edges[i];
      const dx = e.toNode.x - e.fromNode.x;
      const dy = e.toNode.y - e.fromNode.y;
      const dist = Math.sqrt(dx * dx + dy * dy) || 1;
      const force = (dist - 60) * 0.04;

      const fx = (dx / dist) * force;
      const fy = (dy / dist) * force;

      if (!e.fromNode.isRoot) { e.fromNode.vx += fx; e.fromNode.vy += fy; }
      if (!e.toNode.isRoot) { e.toNode.vx -= fx; e.toNode.vy -= fy; }
    }

    this.nodes.forEach(n => {
      if (!n.isRoot) {
        n.vx *= damping;
        n.vy *= damping;
        n.x += n.vx;
        n.y += n.vy;
      }
    });
  };

  NetworkGraph.prototype.render = function() {
    const ctx = this.ctx;
    ctx.clearRect(0, 0, this.width, this.height);

    ctx.save();
    ctx.translate(this.offsetX, this.offsetY);

    this.edges.forEach(e => {
      ctx.beginPath();
      ctx.moveTo(e.fromNode.x, e.fromNode.y);
      ctx.lineTo(e.toNode.x, e.toNode.y);
      ctx.strokeStyle = 'rgba(148, 163, 184, 0.3)';
      ctx.lineWidth = 1.5;
      ctx.stroke();

      if (e.label) {
        const mx = (e.fromNode.x + e.toNode.x) / 2;
        const my = (e.fromNode.y + e.toNode.y) / 2;
        ctx.fillStyle = '#64748B';
        ctx.font = '8px sans-serif';
        ctx.fillText(e.label, mx, my);
      }
    });

    this.nodes.forEach(n => {
      let color = '#10B981';
      if (n.riskScore < 55) color = '#EF4444';
      else if (n.riskScore < 80) color = '#F59E0B';

      ctx.beginPath();
      ctx.arc(n.x, n.y, n.radius + 3, 0, 2 * Math.PI);
      ctx.fillStyle = color === '#EF4444' ? 'rgba(239, 68, 68, 0.25)' : (color === '#F59E0B' ? 'rgba(245, 158, 11, 0.25)' : 'rgba(16, 185, 129, 0.25)');
      ctx.fill();

      ctx.beginPath();
      ctx.arc(n.x, n.y, n.radius, 0, 2 * Math.PI);
      ctx.fillStyle = color;
      ctx.fill();
      ctx.strokeStyle = '#0F172A';
      ctx.lineWidth = 2;
      ctx.stroke();

      ctx.fillStyle = '#F8FAFC';
      ctx.font = n.isRoot ? 'bold 10px sans-serif' : '9px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(n.label, n.x, n.y + n.radius + 11);
    });

    ctx.restore();
  };

  global.NetworkGraph = NetworkGraph;
})(window);
